<script setup lang="ts">
const { t } = useSiteText();
const selected = ref<'read' | 'reading' | 'to read' | null>(null);
const result = ref<HTMLElement>();
const firstChoice = ref<HTMLButtonElement>();
const done = computed(() => selected.value === 'reading');
const feedbackTitle = computed(() => selected.value === 'read' ? 'wrongReadTitle' : selected.value === 'to read' ? 'wrongToReadTitle' : 'successTitle');
const feedbackText = computed(() => selected.value === 'read' ? 'wrongRead' : selected.value === 'to read' ? 'wrongToRead' : 'success');
async function choose(answer: 'read' | 'reading' | 'to read') {
  selected.value = answer;
  if (answer === 'reading') { await nextTick(); result.value?.focus({ preventScroll: true }); }
}
async function reset() { selected.value = null; await nextTick(); firstChoice.value?.focus({ preventScroll: true }); }
</script>
<template>
  <section id="practice-example" class="practice" aria-labelledby="home-practice-title"><div class="practice-inner"><div class="practice-copy"><p class="eyebrow">{{ t('official.v1.home.practice.eyebrow') }}</p><h2 id="home-practice-title"><span class="desktop-only">{{ t('official.v1.home.practice.title') }}</span><span class="mobile-only">{{ t('official.v1.home.practice.mobileTitleFirst') }}<br />{{ t('official.v1.home.practice.mobileTitleSecond') }}</span></h2><p class="intro desktop-only">{{ t('official.v1.home.practice.introFirst') }}<br />{{ t('official.v1.home.practice.introSecond') }}</p><p class="intro mobile-only">{{ t('official.v1.home.practice.mobileIntro') }}</p><p class="caption desktop-only">{{ t('official.v1.home.practice.caption') }}</p></div>
    <div class="exercise"><div class="exercise-top"><span>{{ t('official.v1.home.practice.field') }}</span><span>{{ t('official.v1.home.practice.duration') }}</span></div><div class="sentence" lang="en">{{ t(done ? 'official.v1.home.practice.correctSentence' : 'official.v1.home.practice.sentence') }}</div><p class="translation">{{ t('official.v1.home.practice.translation') }}</p><template v-if="!done"><p class="question">{{ t('official.v1.home.practice.choose') }}</p><div class="choices"><button ref="firstChoice" type="button" :aria-pressed="selected === 'read'" @click="choose('read')">read</button><button type="button" @click="choose('reading')">reading</button><button type="button" :aria-pressed="selected === 'to read'" @click="choose('to read')">to read</button></div></template><div ref="result" class="feedback" :class="{ correct: done, wrong: selected && !done }" :tabindex="done ? -1 : undefined" role="status" aria-live="polite"><template v-if="selected"><strong>{{ t(`official.v1.home.practice.${feedbackTitle}`) }}</strong><p>{{ t(`official.v1.home.practice.${feedbackText}`) }}</p></template><p v-else>{{ t('official.v1.home.practice.initialHint') }}</p></div><button v-if="done" class="restart" type="button" @click="reset">{{ t('official.v1.home.practice.restart') }}</button></div>
  </div></section>
</template>
